use vstd::prelude::*;

verus! {
    // A simple predicate saying when an integer is odd.
    spec fn is_odd(x: i32) -> bool {
        x % 2 != 0
    }

    /// Given a non‐empty vector `a`, return the index of the first odd element,
    /// or `None` if there is no odd element.
    ///
    /// Guarantees:
    ///   - If `Some(idx)` is returned, then
    ///       0 <= idx < a.len(),
    ///       a[idx] is odd,
    ///       and every element before idx is not odd.
    ///   - If `None` is returned, then no element of `a` is odd.
    fn find_first_odd(a: &Vec<i32>) -> Option<usize>
        requires
            a.len() >= 1,
        ensures
            match result {
                Some(idx) =>
                    idx < a.len()
                    && is_odd(a[idx])
                    && forall |j: usize| j < idx ==> !is_odd(a[j]),
                None =>
                    forall |j: usize| j < a.len() ==> !is_odd(a[j]),
            }
    {
        let mut idx: usize = 0;
        // Invariant: we've scanned [0..idx), and found no odd elements there.
        while idx < a.len()
            invariant
                idx <= a.len(),
                forall |j: usize| j < idx ==> !is_odd(a[j]),
            decreases
                a.len() - idx,
        {
            if is_odd(a[idx]) {
                // First odd found at position idx
                return Some(idx);
            }
            idx = idx + 1;
        }
        // No odd element in the entire array
        None
    }
}

